 const decamelize = string => string
 	// Separate capitalized words.
-	.replaceAll(/([A-Z]{2,})(\d+)/g, '$1 $2')
-	.replaceAll(/([a-z\d]+)([A-Z]{2,})/g, '$1 $2')
