import('./index.js').then(({slugifyWithCounter}) => {
  const pool = ['foo','bar','foo 1','foo-1','foo-2','foo bar','Foo Bar','_foo','foo_1','1','2','foo-1-2','x','X','a-1','foo 2','foo 3'];
  let dups = 0, nonEmpty=0;
  for (let i=0;i<2000;i++){
    const s = slugifyWithCounter();
    const used = new Set();
    for (let j=0;j<10;j++){
      const out = s(pool[Math.floor(Math.random()*pool.length)]);
      if (!out) continue;
      nonEmpty++;
      if (used.has(out)) dups++;
      used.add(out);
    }
  }
  console.log('slugs returned:', nonEmpty, 'duplicates:', dups);
});
